function validate([s]) {
  if (typeof s !== 'string' || s.length > 30000) return 's has at most 3 * 10^4 characters.';
  if (s.length === 0) return null;
  if (!/^[-0-9()]+$/.test(s)) return 's may only contain digits, "-", "(" and ")".';
  let i = 0;
  const readNumber = () => {
    const match = /^-?(0|[1-9][0-9]*)/.exec(s.slice(i, i + 13));
    if (!match || match[0] === '-0' || Math.abs(Number(match[0])) > 2 ** 30) return false;
    i += match[0].length;
    return true;
  };
  // children[d] counts the groups already read for the open node at depth d.
  const children = [0];
  if (!readNumber()) return 'Every node must start with an integer between -2^30 and 2^30.';
  while (i < s.length) {
    if (s[i] === '(') {
      if (children[children.length - 1] === 2) return 'A node can have at most two groups.';
      children[children.length - 1]++;
      i++;
      if (!readNumber()) return 'Every group must start with an integer between -2^30 and 2^30.';
      children.push(0);
    } else if (s[i] === ')') {
      if (children.length === 1) return 'The parentheses are not balanced.';
      children.pop();
      i++;
    } else return 'A value must be followed by "(", ")" or the end of s.';
  }
  if (children.length !== 1) return 'The parentheses are not balanced.';
  return null;
}

