function str2tree(s) {
  let index = 0;
  const parse = () => {
    const start = index;
    if (s[index] === '-') {
      index++;
    }
    while (index < s.length && s[index] >= '0' && s[index] <= '9') {
      index++;
    }
    const node = new TreeNode(Number(s.slice(start, index)));
    if (s[index] === '(') {
      index++;
      node.left = parse();
      index++;
    }
    if (s[index] === '(') {
      index++;
      node.right = parse();
      index++;
    }
    return node;
  };
  if (s.length === 0) {
    return null;
  }
  return parse();
}

