function str2tree(s) {
  // Scan left to right with a stack of open nodes: a number becomes a child of the node on top.
  let root = null;
  const stack = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '(') { i++; continue; }
    if (s[i] === ')') { stack.pop(); i++; continue; }
    let j = i + 1;
    while (j < s.length && '0123456789'.includes(s[j])) j++;
    const node = new TreeNode(parseInt(s.substring(i, j), 10));
    if (stack.length === 0) root = node;
    else if (stack[stack.length - 1].left === null) stack[stack.length - 1].left = node;
    else stack[stack.length - 1].right = node;
    stack.push(node);
    i = j;
  }
  return root;
}

