function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const value = () => {
    const r = rand();
    if (r < 0.05) return rand() < 0.5 ? 2 ** 30 : -(2 ** 30);
    if (r < 0.3) return int(-1000, 1000);
    return size === 'large' ? int(-99, 99) : int(-9, 9);
  };
  // Builds a random tree of count nodes as a string; a lone child is always written as the left one.
  const build = (count, depth) => {
    if (count === 0) return '';
    const rest = count - 1;
    let left = depth > 40 ? Math.floor(rest / 2) : int(0, rest);
    let right = rest - left;
    if (left === 0) { left = right; right = 0; }
    const leftText = build(left, depth + 1);
    const rightText = build(right, depth + 1);
    return String(value()) + (left ? `(${leftText})` : '') + (right ? `(${rightText})` : '');
  };
  if (size === 'small') {
    if (rand() < 0.08) return [''];
    if (rand() < 0.15) {
      // A short chain of left children.
      let text = String(value());
      for (let k = int(1, 5); k > 0; k--) text = `${value()}(${text})`;
      return [text];
    }
    return [build(int(1, 9), 0)];
  }
  if (rand() < 0.3) {
    // A deep left spine of 400 nodes, each with a right leaf.
    let text = String(value());
    for (let k = 0; k < 400; k++) text = `${value()}(${text})(${value()})`;
    return [text];
  }
  for (;;) {
    const text = build(int(1100, 1500), 0);
    if (text.length <= 10000) return [text];
  }
}
